/* Home opening: a faceless man with wavy, side-swept hair, ear, neck and shoulders, as small particles.
   Read by the particle opening on the home page. */
window.__manCloud = function (N) {
  var raw = atob(''), NH = 14880, NS = 9120;
  var nh = Math.min(NH, Math.round(N * NH / (NH + NS))), ns = Math.min(NS, N - nh);
  var head = new Float32Array(N * 3), kind = new Float32Array(N), seed = 5;
  var rnd = function () { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; };
  var put = function (k, j) {
    head[k * 3] = -1.9 + raw.charCodeAt(j * 4) / 255 * 3.8 + (rnd() - .5) * .014;
    head[k * 3 + 1] = -2.3 + raw.charCodeAt(j * 4 + 1) / 255 * 3.5999999999999996 + (rnd() - .5) * .014;
    head[k * 3 + 2] = -1.0 + raw.charCodeAt(j * 4 + 2) / 255 * 2.0 + (rnd() - .5) * .008;
  };
  var k = 0;
  for (var i = 0; i < nh; i++, k++) { put(k, i); kind[k] = 1 + raw.charCodeAt(i * 4 + 3) / 255; }
  for (i = 0; i < ns && k < N; i++, k++) { put(k, NH + i); kind[k] = 0; }
  for (; k < N; k++) { put(k, k % NH); kind[k] = 1; }
  return { head: head, kind: kind };
};
